def f(x):
    """Returns the number of trailing zeros in x's decimal representation plus 1, or 0 if x is 0 or odd."""
    if x == 0:
        return 0
    if x % 2 != 0:
        return 0
    x = abs(x)
    count = 0
    while x % 10 == 0:
        count += 1
        x = x // 10
    return count + 1

